":每月判斷一次、看之後 12 個月,相鄰月份的答案幾乎重疊,5 年多只有約 4.7 個獨立期間;命中率略高於 50% 不代表模型有效(舊版基準,是包含樣本外測試期的全期結果,僅供對照:台股 12 個月 58.8% 的 95% 區間是 52.7% ~ 66.0%)。": ": judged monthly with a 12-month horizon, adjacent months' answers almost fully overlap, so 5+ years contain only about 4.7 independent periods; a hit rate slightly above 50% does not mean the model works (old baseline, full-period results including the out-of-sample test period, for comparison only: Taiwan 12-month 58.8%, 95% range 52.7% ~ 66.0%).",
":沒有內建評等;分數與等級只來自你自己建立的模型。分數、估值與回測都是模型輸出,不構成對任何證券的買賣建議。": ": there are no built-in ratings; scores and grades come only from models you build yourself. Scores, valuations and backtests are model outputs and are not recommendations on any security.",
