"Jegadeesh–Titman 發現過去 3–12 個月漲多的股票之後 3–12 個月仍傾向較強,慣例跳過最近 1 個月(12-1 動能),所以加重 12-1 個月動能。Chan、Jegadeesh 與 Lakonishok 發現盈餘動能和價格動能並存,所以成長次之;動能策略偶爾會大幅回撤,留一點財務安全。估值不看(便宜和趨勢常互相抵觸)。": "Jegadeesh–Titman found stocks that rose over the past 3–12 months tended to stay stronger over the next 3–12 months, conventionally skipping the latest month (12-1 momentum), so 12-1 month momentum is emphasized. Chan, Jegadeesh and Lakonishok found earnings and price momentum coexist, so growth is second; momentum strategies occasionally draw down sharply, so a little financial safety remains. Valuation is ignored (value and trend often conflict).",
