"Novy-Marx 發現毛利 ÷ 總資產這類獲利能力指標有和價值相當的溢酬;Asness 等人的 QMJ 把「品質」定義成獲利、成長、安全(低槓桿、低破產風險)與配息,高品質股長期表現較好。所以品質為主、財務安全次之,成長與估值各留一點,避免完全不考慮估值;品質裡加重毛利 ÷ 總資產。": "Novy-Marx found profitability metrics like gross profit ÷ total assets carry a premium comparable to value; QMJ by Asness et al. defines \"quality\" as profitability, growth, safety (low leverage, low distress risk) and dividends, with high-quality stocks doing better over the long run. So quality comes first and financial safety second, with a little left for growth and valuation so valuation is not ignored entirely; within quality, gross profit ÷ total assets is emphasized.",
