"「開始掃描」會更新整組股票的資料;第一次每檔都要抓完整資料(台股 40 檔約 10–20 分鐘)。FinMind 免費額度用完時會用快取或略過部分籌碼資料,之後有快取會快很多。": "\"Start scan\" refreshes data for the whole group; the first time, every stock needs full data (about 10–20 minutes for 40 Taiwan stocks). When the free FinMind quota runs out, cached data is used or some ownership data is skipped; later runs with a cache are much faster.",
"一個平台看完台股、美股的財報、估值、籌碼與新聞;不用寫程式就能組出自己的量化模型,再用不偷看未來的回測檢驗它到底有沒有用。": "One platform for the financials, valuation, ownership flows and news of Taiwan and US stocks. Build your own quantitative model without coding, then test whether it really works with a backtest that never peeks at the future.",
