"三個步驟:自己選一個因子範本、看過權重並勾選你在意的訊號,再存成你的模型。分數與排名只來自你存的模型;存檔後還能在模型工作台細調。": "Three steps: pick a factor template yourself, review its weights, tick the signals you care about, then save it as your model. Scores and rankings come only from models you save; you can fine-tune them later in the model workbench.",
"三個步驟:選一個投資風格、勾選你在意的訊號,馬上看到今天的排名與過去的模擬表現。存檔後還能在模型工作台細調。": "Three steps: choose an investing style, tick the signals you care about, and see today's ranking and simulated past performance right away. After saving you can fine-tune it in the model workbench.",
"三個步驟建立你自己的選股模型:自己選一個因子範本當起點(沒有預設、不推薦),看過權重、調整你在意的訊號,再存成你自己的模型。": "Build your own stock model in three steps: pick a factor template yourself as a starting point (nothing preselected or recommended), review the weights, adjust the signals you care about, then save it as your own model.",
"三個步驟建立你自己的選股模型:選一個投資風格當起點,調整你在意的訊號,馬上看到今天的排名。": "Build your own stock model in three steps: choose an investing style as a starting point, adjust the signals you care about, and see today's ranking immediately.",
