"低 / 中 / 高 / 很高 → 要求安全邊際 15% / 25% / 35% / 45%": "Low / Medium / High / Very high → margin of safety 15% / 25% / 35% / 45%",
"低 beta、低波動股票的風險調整後報酬長期優於高 beta 股(Frazzini–Pedersen 的 BAB、Baker 等人的低波動異常);QMJ 把低 beta、低波動和低槓桿、低破產風險一起歸為「安全」。所以把波動與 beta 放進財務安全面向並以它為主、品質次之,估值留一點避免過度偏向高估值的防禦股。": "Risk-adjusted returns of low-beta, low-volatility stocks have long exceeded high-beta stocks (Frazzini–Pedersen's BAB, Baker et al.'s low-volatility anomaly); QMJ groups low beta and low volatility with low leverage and low distress risk as \"safety\". So volatility and beta go into the financial safety pillar, which comes first, with quality second, and a little valuation so the model does not lean too far toward highly valued defensives.",
