"你選的設定和範例模型完全相同。範例模型的過去表現已經用固定流程驗證過,結果放在「模型驗證」頁;這裡不重算,避免同一個設定被重複測試、越試越像有效。": "Your settings are identical to the sample model. The sample model's past performance was validated with a fixed process and is on the \"Model validation\" page; it is not recomputed here, to avoid testing the same setting repeatedly until it looks effective.",
"你選的設定和開發時的研究基準模型完全相同。它的過去表現已經用固定流程驗證過,整體統計放在「研究紀錄」頁;這裡不重算,避免同一個設定被重複測試、越試越像有效。": "Your setup is identical to the research baseline model used during development. Its past performance was already tested with a fixed procedure, and the overall statistics are on the Research record page; it is not recalculated here, so the same setup isn't tested again and again until it looks effective.",
