"價值": "Value",
"價值(範本)": "Value (template)",
"價值溢酬是最早被記錄的因子之一(Fama–French 的 HML);Graham 主張買價低於價值並要求財務穩健,便宜股裡財務差的常是價值陷阱,所以財務安全次之、品質再次之(Piotroski 的做法)。估值裡加重現金流殖利率與 EV/EBITDA 這類以現金流、企業價值計算的倍數(LSV 用 CF/P;Loughran–Wellman 用 EBITDA/EV)。": "The value premium is among the earliest documented factors (Fama–French HML); Graham argued for prices below value and financial soundness, and cheap stocks with weak finances are often value traps, so financial safety is second and quality third (Piotroski's approach). Valuation emphasizes cash flow yield and multiples based on cash flow and enterprise value such as EV/EBITDA (LSV uses CF/P; Loughran–Wellman uses EBITDA/EV).",
"價格": "Price",
"價格 ≤ 模型估值 × (1 − 安全邊際) → 模型等級 A;≤ × (1 − 安全邊際/2) → 等級 B;±安全邊際/2 內 → 等級 C;以上對稱為等級 D、E。安全邊際由不確定性決定(低 15%、中 25%、高 35%、很高 45%)。長期分數 < 40 降一級;有財務紅旗最高只到等級 C。": "Price ≤ model valuation × (1 − margin of safety) → model grade A; ≤ × (1 − margin of safety/2) → grade B; within ±margin of safety/2 → grade C; symmetric above for grades D and E. The margin of safety depends on uncertainty (low 15%, medium 25%, high 35%, very high 45%). A long-term score < 40 lowers one grade; with a financial red flag the maximum is grade C.",
