"判斷日前 12 個月內已除息的現金股利合計 ÷ 判斷日收盤價(股利換到判斷日的股數基準;還沒除息的不算)": "Cash dividends gone ex in the 12 months before the judgment date ÷ close on the judgment date (dividends restated to the share basis at that date; dividends not yet ex are excluded)",
