"判斷錯誤": "Incorrect",
"判讀:7 個因子一起做 Holm 多重檢定校正(p 值用 Newey–West,考慮自相關)。校正後 p < 0.05 才算「顯著」,但這只是開發期上的統計關係,沒有經過正式檢定與樣本外檢驗,仍不算證實有效。台股前 50 是每個時點當時的名單,含之後下市的公司;權值 40 與美股 40 是今天的名單,有存活者偏誤。": "Reading: the 7 factors are corrected together with Holm multiple testing (p-values use Newey–West to account for autocorrelation). Only an adjusted p < 0.05 counts as \"significant\", but this is only a statistical relationship in the development period, without a formal test or out-of-sample check, so it is still not proven. Taiwan top 50 is the list at each point in time, including later delistings; large-cap 40 and US 40 are today's lists, with survivorship bias.",
