"台股(舊版基準,是包含樣本外測試期的全期結果,僅供對照,不是本頁的開發期數字):「排除等級 D、E」與全部等權的年化差距 +1.6%,95% 區間 −2.0% ~ +5.5%,沒有證實有效;只含最高等級的(−4.1%,區間 −13.8% ~ +5.1%)也沒有證實有效。「勝過大盤」主要來自存活者股票池與大盤不含股利,不是模型能力。": "Taiwan (old baseline, full-period results including the out-of-sample test period, for comparison only, not this page's development-period figures): the annualized gap between \"Excluding grades D and E\" and all equal-weighted is +1.6%, 95% range −2.0% ~ +5.5%, not proven effective; holding only the top grade (−4.1%, range −13.8% ~ +5.1%) is also not proven effective. \"Beating the market\" comes mainly from the survivor universe and a market index without dividends, not model skill.",
