"台股有每日公布的法人買賣超與每週集保分級資料;研究發現台股法人(含外資)整體的交易有資訊優勢,散戶整體則因交易虧損,所以籌碼為主、動能次之(籌碼常和價格趨勢一起出現),估值、品質與財務安全只留一點。注意:籌碼歷史目前沒有放進回測(參數 tw_chips_history 關閉、集保分級沒有歷史),回測時這個面向算不出來。": "Taiwan publishes daily institutional net flows and weekly TDCC tiers; research finds Taiwan institutions (including foreign) have an information edge overall while retail loses from trading overall, so ownership flows come first and momentum second (flows often appear with price trends), with little left for valuation, quality and financial safety. Note: flow history is not in the backtest yet (parameter tw_chips_history is off and TDCC tiers have no history), so this pillar cannot be computed in backtests.",
