"同一份資料一次檢定很多因子,總會有幾個看起來顯著;Holm 校正把這個運氣成分扣掉。": "Testing many factors on the same data will always make a few look significant; Holm correction removes this element of luck.",
"同一個月很多檔股票一起漲跌,彼此不獨立;3 個月與 12 個月期每月取一筆,前後期間會重疊(12 個月期最多重疊 11 個月)。區間是當成獨立樣本算的,會偏窄。價格報酬沒有含股利。": "Many stocks move together within a month and are not independent; 3-month and 12-month horizons take one record per month and overlap (12-month horizons by up to 11 months). Ranges are computed as if samples were independent, so they run narrow. Price returns exclude dividends.",
