"數值的單位和原始指標相同(百分比用小數表示,0.25 = 25%)。線性打分:數值到「差」給 0 分、到「好」給 100 分,中間線性內插;「差」大於「好」代表越小越好。峰值打分:100 − |數值 − 中心| × 斜率。內建規則只能改權重與開關。": "Values use the same unit as the raw metric (percentages as decimals, 0.25 = 25%). Linear scoring: a value at \"bad\" scores 0, at \"good\" scores 100, linearly in between; \"bad\" above \"good\" means smaller is better. Peak scoring: 100 − |value − center| × slope. Built-in rules only allow weight and on/off changes.",
