"模擬報酬沒有經過統計檢驗,期間短、樣本少,不能用來判斷模型有沒有用;模型有沒有用請看「模型驗證」頁。": "Simulated returns have no statistical test; the period is short and the sample small, so they cannot show whether the model works. See the \"Model validation\" page for that.",
"模擬報酬沒有經過統計檢驗,期間短、樣本少,不能用來判斷模型有沒有用;模型有沒有用請看「研究紀錄」頁。": "Simulated returns are not statistically tested; the period is short and the sample small, so they can't tell whether the model works. See the Research record page for that.",
