"模擬選股:和策略 A 相同(長期模型等級 B 以上、短期分數不是偏低、資料完整度 ≥ 60、沒有財務紅旗);已持有的在等級降到 D 以下或出現紅旗前都算候選": "Simulated selection: same as strategy A (long-term model grade B or above, short-term score not low, data completeness ≥ 60, no financial red flags); holdings stay candidates until the grade falls to D or below or a red flag appears",
"樣本": "Sample",
"樣本 {0} 檔(每檔取最早一筆已過 {1} 天的快照);同時檢驗多個面向、沒有做多重檢定校正,|t| ≥ 2 不能算證實有效": "Sample {0} stocks (earliest snapshot per stock older than {1} days); several pillars are tested at once without multiple-testing correction, so |t| ≥ 2 does not count as proven",
"樣本 {0} 檔(每檔取最早一筆已過 {1} 天的快照)。": "Sample {0} stocks (earliest snapshot per stock older than {1} days).",
"樣本 {0} 筆 · 樣本少不要下結論": "Sample {0} records · too few to draw conclusions",
