"樣本不足:需要至少 {0} 檔「分析後已過 {1} 天」的快照才開始計算(目前 {2})。持續使用或定期掃描就會累積。": "Insufficient sample: at least {0} snapshots \"older than {1} days after analysis\" are needed to compute (currently {2}). Continued use or regular scans accumulate them.",
"樣本內歷史回測,單一股票樣本小,只能當參考,不代表未來": "In-sample historical backtest on a single stock with a small sample; reference only, not indicative of the future",
"樣本內調整": "In-sample adjustment",
"樣本外測試": "Out-of-sample test",
"樣本外測試期({0} 以後的股價)只能透過正式程序計算,每個研究階段最多一次;目前用了 {1} 次。這頁不顯示任何樣本外成績。": "The out-of-sample test period (prices from {0} onward) can only be computed through the formal process, at most once per research stage; {1} used so far. This page shows no out-of-sample results.",
"樣本外測試期是 2024-10-01 以後的資料,每個模型系列只有一次乾淨的測試機會。": "The out-of-sample test period is data from 2024-10-01 onward; each model family gets one clean test.",
