"樣本少時不要下結論:少於 {0} 筆標「樣本不足」;就算樣本夠,命中率也沒有附信賴區間、沒有經過正式檢定,不算證實有效。": "Do not draw conclusions from small samples: under {0} records is labeled \"Insufficient sample\"; even with enough, the hit rate has no confidence interval and no formal test, so it is not proven.",
