"營收成長 > 30%(SGI 高),模型容易誤判,僅供參考。": "Revenue growth > 30% (high SGI) can make the model misjudge; reference only.",
"營收成長速度。": "Speed of revenue growth.",
"營收比去年同期多了多少": "Revenue growth vs. the same period last year",
"營收與獲利持續成長是股價長期上漲的來源;台股每月公布營收,月營收年增與創新高是常用的高頻成長訊號。但 Lakonishok 等人發現市場常過度外推過去的高成長(成長股平均報酬反而較低),所以品質次之、估值與財務安全各留一點當煞車。注意:分析師預估成長在回測裡沒有資料。": "Sustained revenue and earnings growth is a source of long-term price gains; Taiwan publishes revenue monthly, and monthly YoY and record highs are common high-frequency growth signals. But Lakonishok et al. found markets often over-extrapolate past high growth (growth stocks averaged lower returns), so quality is second, with a little left for valuation and financial safety as a brake. Note: analyst estimated growth has no data in backtests.",
