"理想:等級越高,跑贏比例越高。平均報酬會被少數報酬極高的股票拉高,看「跑贏比例」比較公平。": "Ideally, higher grades beat the median more often. Average return is pulled up by a few very high-return stocks, so \"share beating the median\" is fairer.",
