"理由欄的等級是「模型內部等級」:美股在其他畫面一律不評等,這裡為了執行模擬規則才使用內部等級。模擬持股是規則的結果,不是對個股的建議。": "Grades in the reason column are \"internal model grades\": US stocks are never graded on other screens, and the internal grade is used here only to run the simulation rules. Simulated holdings are the result of rules, not recommendations on any stock.",
