"用三個步驟自己選一個因子範本(沒有預設、不推薦)、看過權重並調整你在意的訊號,再存成你的模型。": "In three steps, pick a factor template yourself (nothing preselected or recommended), review the weights, adjust the signals you care about, then save it as your model.",
"用三個步驟選範本、調整你在意的訊號,馬上看到今天的排名。也可以從範例模型另存一份,再細調每個指標。": "Choose a template and adjust the signals you care about in three steps, and see today's ranking right away. You can also save a copy of the sample model and fine-tune each metric.",
"用中英文詞典判斷,準確度有限,只當參考": "Judged with Chinese and English dictionaries; limited accuracy, reference only",
"用事先登記的其他判準檢驗(例:機率校準用 Brier 分數比較),或只能在樣本外測試期檢驗。": "Tested with other pre-registered criteria (e.g. probability calibration compared by Brier score), or only testable in the out-of-sample test period.",
"用你的模型對這家公司計算的分數與等級。只是模型輸出,不是買賣建議;下方的資料頁不需要模型。": "Scores and grades your model calculates for this company. They are model output, not a recommendation to buy or sell; the data pages below don't need a model.",
"用你的設定,替股票池裡每一檔重新打長期分數,由高到低排序。只有分數、等級與排名,不是投資建議。": "Using your settings, each stock in the universe gets a new long-term score, sorted high to low. It shows only scores, grades and rankings; it is not investment advice.",
"用你自己的模型替整組股票打分數並排名,整理成可以深入查證的研究清單。H0 Lab 不提供內建模型的排名。": "Score and rank a whole group of stocks with your own model to build a research list you can dig into. H0 Lab provides no built-in model rankings.",
"用均線排列判斷多頭、盤整或空頭": "Classifies uptrend, range or downtrend from moving average alignment",
"用存檔的版本,在 2024-10-01 以前的歷史資料上模擬:每個月依長期分數取前 20% 等權持有,和股票池平均、大盤比較。": "Using the saved version on historical data before 2024-10-01: each month it simulates holding the top 20% by long-term score, equal-weighted, and compares with the universe average and the market.",
"用未來獲利算的本益比。": "P/E based on forward earnings.",
"用目前獲利幾年可以還清負債。": "Years needed to repay debt at current earnings.",
"用目前的現金獲利,幾年能還清淨負債": "Years to repay net debt at current cash earnings",
"用精靈自己選一個因子範本(沒有預設、不推薦),看過權重、調整你在意的訊號,存成你自己的模型。H0 Lab 不提供內建評等。": "In the wizard, pick a factor template yourself (nothing preselected or recommended), review the weights, adjust the signals you care about and save it as your own model. H0 Lab has no built-in ratings.",
"用虛擬資金照模型規則自動模擬交易,看規則實際跑起來的樣子;全部是模擬紀錄,不碰真錢、不下真單,不是對個股的建議。": "Simulates trades automatically with virtual money under the model's rules, to show how the rules actually run. Everything is a simulated record: no real money, no real orders, and no recommendation on any stock.",
"用途:了解財報前後的歷史波動。若平均波動 ±8%,代表歷史上財報前後的價格變動約這個幅度。": "Purpose: understand historical volatility around earnings. An average move of ±8% means prices historically moved about that much around earnings.",
"用這個模型(含還沒存檔的修改)重算一檔股票。只會用已經打開過的報告,不會為了試算去抓資料。代號要完整,例如 2330.TW、NVDA。": "Recomputes one stock with this model (including unsaved changes). It uses only reports already opened and does not fetch data for this. Use the full ticker, e.g. 2330.TW, NVDA.",
"用過去一年實際領到的現金股利算的殖利率。台股現金減資退還的股款不算股利。": "Yield based on cash dividends actually received over the past year. Cash returned through capital reductions in Taiwan does not count as dividends.",
"用錢賺錢的效率": "How efficiently money earns money",
