"看敏感度表 —— 如果只要成長率差一點,結論就翻盤,代表風險高。看不懂的數字按旁邊的 ?。": "Check the sensitivity table: if a small change in growth flips the conclusion, uncertainty is high. Click ? next to any number you do not understand.",
