"研究基準模型不能新增指標;另存成我的模型後就可以。": "You can't add metrics to the research baseline model; save a copy as your own model first.",
"研究基準模型是唯讀的:它的設定只能經過開發時的正式檢定修改。你可以在這裡檢視、試算,或另存一份成我的模型再改。": "The research baseline model is read-only: its settings can only change through the formal tests during development. You can view it here or save a copy as your own model and edit that.",
"研究基準模型用來切短期分數等級的分界(下緣須小於上緣)。自訂模型不輸出短期分數等級,這兩個值目前只影響設定指紋,保留給之後的回測使用。": "Cut-offs the research baseline model uses for short-term score grades (lower must be below upper). Custom models don't output short-term score grades; these two values currently only affect the setup fingerprint and are kept for future backtests.",
"研究基準模型的回測與樣本外測試已經在開發時用正式流程做完,不在工作台重跑;開發期的結果在「研究紀錄」頁,樣本外成績不在網站顯示。另存成我的模型之後,就可以在這裡用開發期回測,和研究基準模型比較。": "The research baseline model's backtest and out-of-sample test were done with the formal procedure during development and are not rerun in the workbench; development-period results are on the Research record page, and out-of-sample results are not shown on the site. After saving a copy as your own model, you can run a development-period backtest here and compare it with the research baseline model.",
"研究檢查清單": "Research checklist",
"研究用途": "Research use",
