"研究筆記": "Research notes",
"研究紀錄": "Research log",
"研究紀錄是歷史資料的統計檢定,不代表未來報酬,也不構成投資建議。": "The research record is a statistical test on historical data. It does not represent future returns and is not investment advice.",
"研究顯示分析師目標價平均偏樂觀約 15%,所以模型估值採用前會先打 9 折。": "Research shows analyst price targets run about 15% optimistic on average, so the model valuation applies a 10% haircut before using them.",
"研究顯示分析師目標價平均偏樂觀約 15%,看隱含空間時要把這點算進去。": "Research shows analyst targets are on average about 15% too optimistic; keep that in mind when reading the implied upside.",
