"範例模型用來切短期分數等級的分界(下緣須小於上緣)。自訂模型不輸出短期分數等級,這兩個值目前只影響設定指紋,保留給之後的回測使用。": "Cut-offs the sample model uses for short-term score levels (lower must be below upper). Custom models output no short-term level; these two values currently only affect the settings fingerprint and are kept for later backtests.",
"範例模型的回測與樣本外測試已經在開發時用正式流程做完,不在工作台重跑;開發期的結果在「模型驗證」頁,樣本外成績不在網站顯示。另存成我的模型之後,就可以在這裡用開發期回測,和範例模型比較。": "The sample model's backtest and out-of-sample test were completed during development with the formal process and are not re-run in the workbench; development-period results are on the \"Model validation\" page, and out-of-sample results are not on the site. After saving as my model, you can backtest on the development period here and compare with the sample model.",
