"美股(舊版基準,是包含樣本外測試期的全期結果,僅供對照,不是本頁的開發期數字):這段期間模型沒有優勢,排除低等級 ≈ 全部等權(年化差距 −0.1%,95% 區間 −1.4% ~ +1.2%);長期分數的 IC 是負的,美股等級目前只能當參考。": "US (old baseline, full-period results including the out-of-sample test period, for comparison only, not this page's development-period figures): the model had no edge in this period; excluding low grades ≈ all equal-weighted (annualized gap −0.1%, 95% range −1.4% ~ +1.2%); the long-term score's IC is negative, so US grades are for reference only for now.",
"美股:5 年回測顯示只因估值偏高而給的低等級命中率不到 5 成,等級維持 C(有財務紅旗才會更低)": "US: a 5-year backtest shows that low grades based only on high valuation were right less than half the time, so the grade stays at C (it goes lower only with financial red flags)",
