"這些是即時追蹤紀錄(唯一真正沒看過的樣本):樣本累積後用來檢驗事先登記的研究假設;看完結果直接改權重就是資料窺探,所以任何改動都要先事先登記、再通過正式檢定。": "These are live tracking records (the only truly unseen sample): once accumulated, they test pre-registered research hypotheses. Changing weights right after seeing results is data snooping, so any change must be pre-registered and then pass a formal test.",
