"這是存檔前那個版本的結果;模型已經改過,請重跑。": "These results are from the version before saving; the model has changed, so please re-run.",
"這是研究工具:分數、等級與排名只是依你的選擇重新計算的模型輸出;過去表現只是模擬,不代表未來,不構成投資建議,也不保證任何報酬。": "This is a research tool: scores, grades and rankings are model outputs recomputed from your choices; past performance is only a simulation, does not represent the future, is not investment advice and guarantees no return.",
