"這是這檔股票自己的歷史,樣本有限,也是樣本內結果。只是統計描述,不是預測,也不是對這檔股票的建議。": "This is this stock's own history, with a limited, in-sample result. It is only a statistical description: not a forecast and not a recommendation on this stock.",
