"這次證據:{0}。建議:{1}。": "Evidence this time: {0}. Suggestion: {1}.",
"這裡只做研究與模擬,不接任何券商或交易所、不會下真單。模擬帳戶的報酬只是模型規則在虛擬帳戶的紀錄,不代表未來報酬,也不構成投資建議。": "This is research and simulation only: no connection to any broker or exchange, and no real orders. Simulated account returns are only a record of model rules in a virtual account; they do not represent future returns and are not investment advice.",
"這裡只給分布": "Only the distribution is given here",
"這裡只顯示用你的模型重算的分數與等級;下方報告的其他內容(公平價、各分頁)仍是範例模型的結果。": "Only the scores and grades recomputed with your model are shown here; the rest of the report below (fair value, each tab) is still the sample model's result.",
"這裡只顯示開發期的回測": "Only development-period backtests are shown here",
"這裡提供 DCF、蒙地卡羅、反向 DCF、本益比河流、EPV、同業倍數等工具。每個工具的假設都標了預設值的來源,DCF 與本益比法可以在下方自己調整。\n        H0 Lab 不把各方法綜合成單一公平價,也不提供買進或賣出價位;結果只是依假設推算的數字,不是預測,也不是建議。": "This page offers DCF, Monte Carlo, reverse DCF, P/E river, EPV, peer multiples and other tools. Each tool's default assumptions show where they come from, and you can adjust the DCF and P/E method below. H0 Lab does not combine the methods into a single fair value and gives no buy or sell prices; results are numbers derived from assumptions, not forecasts or recommendations.",
"這頁說明模型怎麼算,不代表模型有效,也不構成投資建議;模型有沒有用請看「模型驗證」頁。": "This page explains how the model computes; it does not mean the model works and is not investment advice. See the \"Model validation\" page for whether the model works.",
"這頁說明模型怎麼算,不代表模型有效,也不構成投資建議;研究結果請看「研究紀錄」頁。開源版不提供內建模型的個股評等,分數只來自你自己的模型。": "This page explains how models are calculated; it does not mean they work and is not investment advice. See the Research record page for results. The open-source edition gives no built-in per-stock ratings; scores come only from your own models.",
