"長期模型等級改用長期分數在正式股票池(台股前 50 時點名單、美股大型 40)最近一個回測判斷日的固定分位:後 10% 為 E、次 20% 為 D、中間 40% 為 C、次 20% 為 B、前 10% 為 A,分位規則和回測相同(切點來自回測的分數分布;回測沒有分析師與同業資料,網站的長期分數和回測不完全可比);公平價與安全邊際照樣顯示,但不決定等級。沒有公平價時不評等;還沒有分位切點檔時暫時沿用舊規則,並在等級理由中標示。": "The long-term model grade now uses fixed percentiles of the long-term score in the formal universe (Taiwan top 50 point-in-time list, US large-cap 40) on the latest backtest judgment date: bottom 10% is E, next 20% D, middle 40% C, next 20% B, top 10% A, the same percentile rule as the backtest (cut points come from the backtest score distribution; the backtest lacks analyst and peer data, so the site's long-term score is not fully comparable); fair value and margin of safety are still shown but do not set the grade. No grade without a fair value; until a cut-point file exists the old rule is used, as noted in the grade reason.",
