"高殖利率要確認是不是來自股價大跌,以及股利能不能持續": "For a high yield, check whether it comes from a price drop and whether the dividend can last",
"高等級的命中率": "Hit rate of high grades",
"高股息研究看重三件事:殖利率夠不夠、是不是年年都配、配息能不能持續。Graham 給防禦型投資人的條件包含長期不間斷配息與財務穩健;高殖利率常是股價大跌造成的(殖利率陷阱),所以財務安全與品質(配息穩定、現金流)和估值(殖利率)權重相近,估值裡也加重自由現金流殖利率(配息的來源)。": "High-dividend research looks at three things: whether the yield is high enough, whether dividends are paid every year, and whether they can continue. Graham's conditions for the defensive investor include long uninterrupted dividends and financial soundness; high yields are often caused by price falls (yield traps), so financial safety and quality (dividend stability, cash flow) are weighted close to valuation (yield), and valuation also emphasizes free cash flow yield (the source of dividends).",
